<script setup>
import { computed, onMounted, ref } from 'vue'

const props = defineProps({ permissions: { type: Array, default: () => [] }, roles: { type: Array, default: () => [] }, userId: { type: Number, default: 0 } })
const can = (permission) => props.permissions.includes(permission)
const billingOnly = computed(() => props.roles.includes('Billing') && !can('additional-charges.view'))
const rows = ref([])
const dashboard = ref({})
const options = ref({ shipments: [], departments: [], categories: [], expenses: [] })
const selected = ref(null)
const busy = ref(false)
const loading = ref(true)
const error = ref('')
const success = ref('')
const createOpen = ref(false)
const editingId = ref(null)
const form = ref({ shipment_id: '', department: '', category: 'other', description: '', justification: '', actual_cost: '', proposed_amount: '', currency: 'PHP', expense_ids: [], tax_treatment: 'none', notes: '' })
const decision = ref({ decision: 'approved', approved_amount: '', representative: '', remarks: '', responded_at: new Date().toISOString().slice(0, 16) })
const review = ref({ decision: 'approve', reason: '' })
const file = ref(null)
const evidenceType = ref('carrier_invoice')
const selectedShipment = computed(() => options.value.shipments.find((item) => String(item.id) === String(form.value.shipment_id)))
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || ''

async function api(url, settings = {}) {
  const response = await fetch(url, { credentials: 'same-origin', ...settings, headers: { Accept: 'application/json', ...(settings.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(settings.headers || {}), ...(settings.method && settings.method !== 'GET' ? { 'X-CSRF-TOKEN': csrf } : {}) } })
  const body = response.status === 204 ? {} : await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(body.message || (response.status === 403 ? 'Your role is not authorized for this action.' : response.status === 401 ? 'Your sign-in session expired. Sign in again.' : 'The request could not be completed.'))
  return body
}

async function load() {
  loading.value = true; error.value = ''
  try {
    const listPath = billingOnly.value ? '/api/additional-charges/billing-eligibility' : '/api/additional-charges'
    const [list, summary] = await Promise.all([api(listPath), billingOnly.value ? Promise.resolve({ data: {} }) : api('/api/additional-charges/dashboard')])
    rows.value = list.data?.data || list.data || []
    dashboard.value = summary.data || {}
    if (can('additional-charges.create')) options.value = (await api('/api/additional-charges/options')).data
  } catch (e) { error.value = e.message } finally { loading.value = false }
}
async function openRow(row) { try { selected.value = (await api(`/api/additional-charges/${row.id}`)).data } catch (e) { error.value = e.message } }
async function submitForm() {
  busy.value = true; error.value = ''; success.value = ''
  try { const values = { ...form.value, shipment_id: Number(form.value.shipment_id), expense_ids: form.value.expense_ids.map(Number) }; const result = editingId.value ? await api(`/api/additional-charges/${editingId.value}`, { method: 'PUT', body: JSON.stringify(values) }) : await api('/api/additional-charges', { method: 'POST', body: JSON.stringify(values) }); createOpen.value = false; success.value = `${result.data.reference} was saved.`; editingId.value = null; await load(); await openRow(result.data) }
  catch (e) { error.value = e.message } finally { busy.value = false }
}
function editSelected() { editingId.value = selected.value.id; form.value = { ...form.value, shipment_id: String(selected.value.shipment_id), department: selected.value.department, category: selected.value.category, description: selected.value.description, justification: selected.value.justification, actual_cost: selected.value.actual_cost, proposed_amount: selected.value.proposed_amount, currency: selected.value.currency, notes: selected.value.notes || '' }; selected.value = null; createOpen.value = true }
async function action(path, body) { busy.value = true; error.value = ''; success.value = ''; try { const result = await api(`/api/additional-charges/${selected.value.id}/${path}`, { method: 'POST', body: JSON.stringify(body) }); selected.value = result.data; success.value = 'The change was recorded.'; await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function uploadEvidence() {
  if (!file.value) return
  busy.value = true; error.value = ''
  const data = new FormData(); data.append('file', file.value); data.append('document_type', evidenceType.value)
  try { const result = await api(`/api/additional-charges/${selected.value.id}/evidence`, { method: 'POST', body: data }); selected.value = result.data; success.value = 'Evidence uploaded to private storage.'; file.value = null; await load() }
  catch (e) { error.value = e.message } finally { busy.value = false }
}
function money(amount, currency) { return `${currency || ''} ${Number(amount || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
onMounted(load)
</script>

<template>
  <main class="acr-workspace">
    <header class="acr-heading"><div><span class="acr-kicker">INTERFREIGHT GROUP / COMMERCIAL CONTROL</span><h1>{{ billingOnly ? 'Approved Additional Charges' : 'Additional Charges' }}</h1><p>{{ billingOnly ? 'Read-only billing eligibility backed by verified client decisions.' : 'Review unexpected costs, client decisions, company exposure, and shipment impact.' }}</p></div><button v-if="can('additional-charges.create')" class="ifc-primary" @click="createOpen = true">Add Charge Request</button></header>
    <div v-if="error" class="acr-alert" role="alert">{{ error }} <button @click="load">Retry</button></div><div v-if="success" class="acr-success" role="status">{{ success }}</div>
    <section v-if="!billingOnly" class="acr-kpis"><article><small>Total Requests</small><b>{{ dashboard.total ?? '—' }}</b></article><article><small>Internal Review</small><b>{{ dashboard.internal_pending ?? '—' }}</b></article><article><small>Client Decision</small><b>{{ dashboard.client_pending ?? '—' }}</b></article><article><small>Approved / Partial</small><b>{{ (dashboard.approved ?? 0) + (dashboard.partial ?? 0) }}</b></article><article><small>Rejected</small><b>{{ dashboard.rejected ?? '—' }}</b></article><article><small>Missing Evidence</small><b>{{ dashboard.missing_evidence ?? '—' }}</b></article></section>
    <section class="acr-panel"><div class="acr-panel-head"><div><h2>{{ billingOnly ? 'Billing eligibility register' : 'Request register' }}</h2><p>Pending and rejected proposals are excluded from billable value.</p></div><span>{{ rows.length }} records</span></div><div class="acr-table-wrap"><table><thead><tr><th>REFERENCE / JOB</th><th>CLIENT</th><th>DEPARTMENT / CATEGORY</th><th>ACTUAL COST</th><th>PROPOSED</th><th>APPROVED</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ row.reference }}</b><small>{{ row.job_number || 'Job not available' }}</small></td><td>{{ row.company_name }}</td><td>{{ row.department }}<small>{{ row.category.replaceAll('_', ' ') }}</small></td><td>{{ money(row.actual_cost, row.currency) }}</td><td>{{ money(row.proposed_amount, row.currency) }}</td><td>{{ row.approved_amount ? money(row.approved_amount, row.currency) : '—' }}</td><td><span :class="['acr-badge', row.client_status]">{{ row.client_status.replaceAll('_', ' ') }}</span><small>{{ row.internal_status.replaceAll('_', ' ') }}</small></td><td><button class="acr-link" @click="openRow(row)">{{ billingOnly ? 'View authorization' : 'Open' }}</button></td></tr><tr v-if="!rows.length"><td colspan="8" class="acr-empty">{{ loading ? 'Loading authorized charge records…' : 'No additional charge requests are available.' }}</td></tr></tbody></table></div></section>

    <div v-if="selected" class="acr-overlay" @click.self="selected = null"><section class="acr-modal acr-detail" role="dialog" aria-modal="true" :aria-label="`Additional charge ${selected.reference}`"><header><div><span>REQUEST HISTORY · {{ selected.reference }}</span><h2>{{ selected.description }}</h2><p>{{ selected.job_number }} · {{ selected.company_name }}</p></div><button class="acr-close" aria-label="Close" @click="selected = null">×</button></header><dl><dt>Justification</dt><dd>{{ selected.justification }}</dd><dt>Internal review</dt><dd>{{ selected.internal_status.replaceAll('_', ' ') }}</dd><dt>Client decision</dt><dd>{{ selected.client_status.replaceAll('_', ' ') }}</dd><dt>Actual cost</dt><dd>{{ money(selected.actual_cost, selected.currency) }}</dd><dt>Proposed / approved</dt><dd>{{ money(selected.proposed_amount, selected.currency) }} / {{ selected.approved_amount ? money(selected.approved_amount, selected.currency) : 'Not approved' }}</dd><dt>Loss classification</dt><dd>{{ selected.classification.replaceAll('_', ' ') }}</dd><dt>Original baseline</dt><dd>{{ selected.quotation_id ? `Quotation #${selected.quotation_id} · version ${selected.baseline_version || 'not recorded'}` : 'No accepted quotation baseline linked' }}</dd></dl>
      <div v-if="can('additional-charges.submit') && ['draft','revision_requested'].includes(selected.internal_status)" class="acr-actions"><button v-if="can('additional-charges.update') && selected.requester_id === userId" class="acr-button" @click="editSelected">Edit Draft</button><button class="ifc-primary" :disabled="busy" @click="action('submit', {})">Submit for Review</button></div>
      <form v-if="can('additional-charges.internal-review') && ['submitted','under_review'].includes(selected.internal_status)" class="acr-inline-form" @submit.prevent="action('review', review)"><label>Internal decision<select v-model="review.decision"><option value="approve">Approve for client request</option><option value="request_revision">Request revision</option><option value="reject">Reject request</option></select></label><label>Reviewer remarks<textarea v-model="review.reason" required maxlength="2000" /></label><button class="ifc-primary" :disabled="busy || !review.reason">Record review</button></form>
      <div v-if="can('additional-charges.client-request.prepare') && selected.client_status === 'awaiting_request'" class="acr-actions"><button class="ifc-primary" @click="action('client-request', {})">Record client request prepared</button><small>Send the request through your normal client channel; this action sends nothing externally.</small></div>
      <form v-if="can('additional-charges.client-response.record') && selected.client_status === 'pending'" class="acr-inline-form" @submit.prevent="action('client-decision', decision)"><label>Client response<select v-model="decision.decision"><option value="approved">Approved</option><option value="partially_approved">Partially approved</option><option value="rejected">Rejected</option><option value="no_response">No response yet</option></select></label><label v-if="['approved','partially_approved'].includes(decision.decision)">Approved amount<input v-model="decision.approved_amount" type="number" min="0.01" step="0.01" required /></label><label v-if="decision.decision !== 'no_response'">Client representative<input v-model="decision.representative" maxlength="180" /></label><label>Remarks / response evidence summary<textarea v-model="decision.remarks" required maxlength="2000" /></label><button class="ifc-primary" :disabled="busy || !decision.remarks">Record decision</button><small>Approval requires separately verified evidence before it can be recorded.</small></form>
      <section class="acr-evidence"><h3>Evidence and decision history</h3><div v-for="evidence in selected.evidence" :key="evidence.id" class="acr-evidence-row"><span>{{ evidence.document_type.replaceAll('_',' ') }} · {{ evidence.original_name }} <b>{{ evidence.verification_status }}</b></span><a :href="`/api/additional-charges/evidence/${evidence.id}/download`" target="_blank" rel="noopener">Download</a><button v-if="can('additional-charges.client-response.verify') && evidence.verification_status === 'pending'" class="acr-link" @click="action(`evidence/${evidence.id}/verify`, { decision: 'verified', reason: 'Document and client response evidence verified.' })">Verify evidence</button></div><p v-if="!selected.evidence.length">No evidence uploaded.</p><form v-if="can('additional-charges.client-response.record') || can('additional-charges.create')" class="acr-upload" @submit.prevent="uploadEvidence"><label>Evidence type<select v-model="evidenceType"><option value="receipt">Expense receipt</option><option value="carrier_invoice">Carrier invoice</option><option value="vendor_document">Vendor document</option><option value="email_approval">Client approval email</option><option value="client_letter">Client letter</option><option value="signed_decision">Signed client decision</option><option value="incident_report">Incident report</option><option value="other">Other supporting file</option></select></label><input type="file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.xls,.xlsx" @change="file = $event.target.files?.[0] || null"><button class="acr-button" :disabled="busy || !file">Upload evidence</button></form><ol><li v-for="(event, index) in selected.history" :key="index"><b>{{ event.event.replaceAll('_',' ') }}</b><span>{{ event.actor || 'System' }} · {{ new Date(event.created_at).toLocaleString() }}</span><small>{{ event.reason }}</small></li></ol></section>
      <footer><span v-if="selected.billing_eligible" class="acr-success">Versioned commercial authorization exists. Original quotation remains unchanged.</span><button class="acr-button" @click="selected = null">Close</button></footer>
    </section></div>

    <div v-if="createOpen" class="acr-overlay" @click.self="createOpen = false"><form class="acr-modal" @submit.prevent="submitForm"><header><div><span>COMMERCIAL EXCEPTION</span><h2>{{ editingId ? 'Edit Additional Charge Request' : 'New Additional Charge Request' }}</h2><p>Unexpected costs need review and explicit client approval before billing.</p></div><button type="button" class="acr-close" aria-label="Close" @click="createOpen = false">×</button></header><div class="acr-fields"><label>Shipment / Job<select v-model="form.shipment_id" required :disabled="Boolean(editingId)"><option value="">Choose assigned shipment</option><option v-for="item in options.shipments" :key="item.id" :value="item.id">{{ item.job_number || item.reference }} · {{ item.client?.company_name }}</option></select></label><label>Department<select v-model="form.department" required :disabled="Boolean(editingId)"><option v-for="item in options.departments" :key="item">{{ item }}</option></select></label><label>Category<select v-model="form.category"><option v-for="item in options.categories" :key="item" :value="item">{{ item.replaceAll('_',' ') }}</option></select></label><label>Currency<input v-model="form.currency" maxlength="3" pattern="[A-Z]{3}" required :disabled="Boolean(editingId)"></label><label>Description<input v-model="form.description" maxlength="220" required></label><label>Reason / justification<textarea v-model="form.justification" maxlength="4000" required /></label><label>Actual additional cost<input v-model="form.actual_cost" type="number" min="0.01" step="0.01" required></label><label>Proposed charge to client<input v-model="form.proposed_amount" type="number" min="0.01" step="0.01" required></label><fieldset v-if="!editingId" class="acr-cost-checks"><legend>Link verified expenses (optional)</legend><label v-for="item in options.expenses.filter(expense => String(expense.shipment_id) === String(form.shipment_id) && expense.department === form.department && expense.currency === form.currency)" :key="item.id"><input v-model="form.expense_ids" type="checkbox" :value="item.id">{{ item.reference }} · {{ item.description }} · {{ money(item.amount, item.currency) }}</label><small>Where linked, total cost must match verified expense amounts and currency.</small></fieldset><label>Notes<textarea v-model="form.notes" maxlength="2000" /></label></div><footer><button type="button" class="acr-button" @click="createOpen = false; editingId = null">Cancel</button><button class="ifc-primary" :disabled="busy">{{ editingId ? 'Save Changes' : 'Save Draft' }}</button></footer></form></div>
  </main>
</template>

<style scoped>
.acr-workspace{display:grid;gap:15px;min-width:0;color:#29495f}.acr-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:14px}.acr-heading h1{margin:5px 0;color:#173b59;font:700 27px Manrope,sans-serif}.acr-heading p{margin:0;color:#718398;font-size:12px}.acr-kicker{color:#1681a3;font-size:9px;font-weight:800;letter-spacing:.12em}.acr-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}.acr-kpis article{display:grid;gap:8px;padding:14px;border:1px solid #dce6ed;border-radius:8px;background:#fff}.acr-kpis small{color:#75879a;font-size:10px;font-weight:700}.acr-kpis b{color:#17486a;font:700 20px Manrope}.acr-panel{min-width:0;overflow:hidden;border:1px solid #dce6ed;border-radius:8px;background:#fff}.acr-panel-head{display:flex;justify-content:space-between;align-items:center;padding:15px 17px;border-bottom:1px solid #e8eef2}.acr-panel-head h2{margin:0;color:#1c4564;font:700 15px Manrope}.acr-panel-head p{margin:5px 0 0;color:#7b8c98;font-size:11px}.acr-panel-head>span{color:#82929d;font-size:10px}.acr-table-wrap{max-width:100%;overflow-x:auto}.acr-table-wrap table{width:100%;min-width:850px;border-collapse:collapse}.acr-table-wrap th{height:37px;padding:0 11px;background:#f5f8fa;color:#7a8b98;text-align:left;font-size:9px;letter-spacing:.06em;white-space:nowrap}.acr-table-wrap td{padding:10px 11px;border-top:1px solid #edf1f4;color:#425e72;font-size:11px;vertical-align:top}.acr-table-wrap td small{display:block;margin-top:4px;color:#8695a0;font-size:9px}.acr-empty{padding:24px!important;text-align:center;color:#7b8c98!important}.acr-badge{display:inline-flex;padding:4px 8px;border-radius:30px;background:#edf2f5;color:#60798b;font-size:9px;font-weight:700;white-space:nowrap;text-transform:capitalize}.acr-badge.approved,.acr-badge.partially_approved{background:#e9f7ef;color:#31744e}.acr-badge.pending,.acr-badge.submitted{background:#fff6e8;color:#93692e}.acr-badge.rejected{background:#fff0ef;color:#a5413b}.acr-link{border:0;background:transparent;color:#11789b;font-weight:700;font-size:11px}.acr-alert,.acr-success{padding:11px 14px;border:1px solid #efc4bf;border-radius:7px;background:#fff3f1;color:#9d413d;font-size:12px}.acr-success{border-color:#c6e2d1;background:#f0faf4;color:#347650}.acr-alert button{border:0;background:none;color:inherit;text-decoration:underline}.acr-overlay{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:16px;background:#102c4980}.acr-modal{display:grid;gap:14px;width:min(720px,100%);max-height:92vh;overflow:auto;padding:20px;border:1px solid #dbe5ec;border-radius:10px;background:#fff;box-shadow:0 20px 70px #10263a40}.acr-modal>header{display:flex;justify-content:space-between;gap:12px}.acr-modal>header span{color:#1681a3;font-size:9px;font-weight:800;letter-spacing:.1em}.acr-modal h2{margin:4px 0;color:#1d4563;font:700 18px Manrope}.acr-modal header p{margin:4px 0;color:#718398;font-size:12px}.acr-close{border:0;background:transparent;color:#60798d;font-size:24px}.acr-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.acr-fields label,.acr-inline-form label{display:grid;gap:5px;color:#526d80;font-size:10px;font-weight:700}.acr-fields input,.acr-fields select,.acr-fields textarea,.acr-inline-form input,.acr-inline-form select,.acr-inline-form textarea{width:100%;min-width:0;min-height:38px;padding:8px 10px;border:1px solid #d3dfe7;border-radius:6px;background:#fff;color:#34566e;font:11px 'DM Sans',sans-serif}.acr-fields textarea,.acr-inline-form textarea{min-height:72px;resize:vertical}.acr-fields label:nth-child(5),.acr-fields label:nth-child(6),.acr-fields label:nth-child(9),.acr-fields label:nth-child(10){grid-column:1/-1}.acr-fields small,.acr-inline-form small{color:#82919d;font-weight:400}.acr-modal>footer,.acr-detail>footer{display:flex;justify-content:flex-end;align-items:center;gap:9px;padding-top:10px;border-top:1px solid #e8edf1}.acr-button{min-height:36px;padding:0 12px;border:1px solid #cfdce6;border-radius:6px;background:#fff;color:#285978;font-size:11px;font-weight:650}.acr-detail dl{display:grid;grid-template-columns:150px 1fr;gap:8px;margin:0}.acr-detail dt{color:#7a8c98;font-size:11px}.acr-detail dd{margin:0;color:#34566e;font-size:11px}.acr-inline-form{display:grid;gap:10px;padding:12px;border:1px solid #e0eaf0;border-radius:8px;background:#f8fafb}.acr-actions{display:grid;justify-items:start;gap:7px}.acr-actions small{color:#748695}.acr-evidence{padding-top:12px;border-top:1px solid #e7edf2}.acr-evidence h3{margin:0 0 9px;color:#294f69;font-size:13px}.acr-evidence-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:8px 0;border-bottom:1px solid #edf1f4;color:#526d80;font-size:11px}.acr-evidence-row span{flex:1}.acr-evidence-row a{color:#11789b}.acr-upload{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:10px 0}.acr-evidence ol{padding-left:20px;color:#526d80;font-size:11px}.acr-evidence li{padding:5px 0}.acr-evidence li span,.acr-evidence li small{display:block;color:#84939d}.acr-evidence li b{text-transform:capitalize}.acr-detail>footer{justify-content:space-between}.acr-detail>footer .acr-success{font-size:10px}.acr-cost-checks{display:grid;gap:6px;padding:10px;border:1px solid #dbe5ec;border-radius:6px}.acr-cost-checks label{display:flex;align-items:center;gap:8px;min-height:28px}.acr-cost-checks input{width:15px;min-height:15px;accent-color:#1683a4}
@media(max-width:760px){.acr-heading{align-items:flex-start;flex-direction:column}.acr-heading h1{font-size:23px}.acr-fields{grid-template-columns:1fr}.acr-fields label:nth-child(n){grid-column:1}.acr-modal{padding:15px}.acr-detail dl{grid-template-columns:1fr;gap:3px}.acr-detail dd{margin-bottom:8px}.acr-detail>footer{align-items:flex-start;flex-direction:column}}
</style>
